import os
import json

class HomeConfig:
    base_cfg: str = ""
    cfg_file: str = ""

    def __init__(self, cfg_file) -> None:
        """On startup, this sets the base config directory"""
        self.base_cfg = os.path.expanduser("~") + "/.config/"
        self.cfg_file = self.base_cfg + cfg_file

    def set(self, path: str) -> None:
        """Adds the path to base_cfg. 'path' can include a
        subdirectory. ex: homeconfig.set_config('git/gitk')"""

        self.cfg_file = self.base_cfg + path;

    def get(self) -> str:
        """Returns the name of the config file"""
        return self.cfg_file

    def read(self) -> str:
        """Reads the config file and returns its content"""
        try:
            with open(self.cfg_file, 'r') as c:
                cfg = c.read()
        except FileNotFoundError:
            return ""
        return cfg

    def read_json(self) -> dict:
        """Reads the config file, parses it as a JSON file,
        and returns its content as a dict"""
        with open(self.cfg_file, 'r') as j:
            cfg = json.load(j)
        return cfg
